-- ============================================================================================================
-- IMPORTACAO DO HISTORICO DE VENDAS REAL DA NORD PIZZA (Cardapio Web + Saipos), a pedido do Matheus, depois do
-- reset de faturamento feito na migration 20261014010000_reset_faturamento_saipos (PR #510).
--
-- Fonte: duas planilhas Excel reais de analise historica de vendas (relatorios MENSAL/DIARIO ja agregados pelo
-- proprio sistema de origem, nao exports de transacao bruta):
--   - Cardapio Web: 27/06/2023 a 02/10/2024 (inclusive)
--   - Saipos:       03/10/2024 em diante
-- O corte entre as duas fontes foi confirmado explicitamente pelo Matheus, assim como a decisao de fazer uma
-- importacao fiel ("Opcao A"): SOMENTE os numeros agregados que as planilhas realmente tem, SEM fabricar
-- pedido/venda individual sintetica. Por isso esta migration so grava SalesEntry (um por dia, agregado) e
-- ImportedSaleItem (um por produto/mes, agregado) -- nao cria nenhuma linha em Sale/SaleItem (granular), que
-- exigiria dado por pedido que as planilhas nao tem. O dashboard de Faturamento por hora/canal continua vazio
-- para as datas historicas -- e esperado, nao e bug.
--
-- Os numeros foram extraidos das planilhas e reconciliados mes a mes contra a aba "Mensal" de cada arquivo
-- (a aba com formula/conferencia propria) ANTES desta migration ser gerada -- bateu em todos os meses, com uma
-- unica diferenca de R$ 193,40 em abr/2025 no relatorio de Itens do Saipos, que a propria planilha ja
-- documenta como imprecisao conhecida do relatorio (nao e erro desta importacao).
--
-- Escopo: SOMENTE a empresa 'nord-pizza' (Empresa.key). A Zarki Sushi ('zarki-sushi') fica zerada de proposito
-- -- nao faz parte desta tarefa, aguarda os arquivos dessa loja -- por isso o escopo e sempre feito via
-- subquery por key, nunca hardcodando um empresaId.
--
-- Sem mudanca de schema -- so DML (INSERT), igual a migration de reset que esta migration complementa.
-- ============================================================================================================

-- ---------------------------------------------------------------------------
-- SalesEntry: 1111 linhas (uma por dia, 456 do Cardapio Web + 655 do Saipos)
-- ---------------------------------------------------------------------------

